style.css:
/* Univerzálny jemný pastelový štýl (Soft & Wet) */
body {
    background-color: #f0f4f8 !important; /* Veľmi jemná modro-biela */
    color: #4a5568 !important;            /* Tmavšia sivá namiesto ostrej čiernej */
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif !important;
}

/* Úprava odkazov */
a {
    color: #a3bffa !important; /* Jemná pastelová modrá */
    transition: color 0.3s ease;
}

a:hover {
    color: #b794f4 !important; /* Jemná fialová pri prejdení myšou */
}

/* Zjemnenie kontajnerov a blokov na stránke */
div, section, article {
    background-color: rgba(255, 255, 255, 0.8) !important;
    border-radius: 8px !important;
    border-color: #e2e8f0 !important;
}

/* Úprava tlačidiel */
button, input[type="submit"] {
    background: linear-gradient(135deg, #ebf8ff, #faf5ff) !important;
    border: 1px solid #e2e8f0 !important;
    color: #6b46c1 !important;
    border-radius: 20px !important;
    padding: 8px 16px !important;
    cursor: pointer;
}
